    uRivPinkLo: { value: lin(0.45, 0.03, 0.42) },
    uRivPink: { value: lin(0.85, 0.07, 0.75) },
    uRivPinkHi: { value: lin(1.05, 0.42, 1.0) },
    uRivFoam: { value: lin(0.95, 0.92, 1.05) },
    uRivFoamLav: { value: lin(0.62, 0.52, 0.95) },
    uRivFoamBlue: { value: lin(0.32, 0.36, 0.9) },
    uRivGlow: { value: new THREE.Color(glow.color) },
    uRivGlowR: { value: new THREE.Vector3(glow.near, glow.far, glow.strength) },
    /** W11: depth of the seam from the locked 05 eye (ForcedTunnel.D0) — screen-isotropic foam cells */
    uRivD0: { value: d0 },
    ...(flow ? { uRivRipple: { value: flow.ripple }, uRivTime: flow.time, uRivFlow: { value: flow.speed } } : {}),
  };
  // `?proj05=1`: the approved water baked onto the far block (proj05_F.png); off: nothing below is used
  const pj = PROJ05 ? proj05Far() : null;
  if (pj) Object.assign(uniforms, pj.uniforms);
  mat.onBeforeCompile = (shader) => {
