  float d = length(vP);
  float ang = atan(vP.y, vP.x);
  float nS = clamp(floor(px / 8.0), 5.0, 16.0);
  float sc = abs(sin(ang * nS * 0.5 + vInst.y * 31.0));
  float amp = 0.11 * smoothstep(16.0, 34.0, px) * smoothstep(0.45, -0.35, vP.y / max(d, 1e-3));
  float R = 1.0 - amp * (1.0 - sc);
