  ${FRAG_TAIL}
}
`;

function makeBankBubbleMaterial() {
  const uniforms = withFog({
    uTime: { value: 0 },
    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
